void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / min(iResolution.x, iResolution.y);
    float dist = length(uv);

    // Tăng hiệu ứng tunnel bằng cách biến dạng không gian UV
    float tunnelStrength = 2.0;
    float tunnelDepth = 1.0 - exp(-dist * tunnelStrength);
    uv *= mix(1.0, tunnelDepth, 0.5); // Biến dạng UV để tạo độ sâu

    // Các tham số xoáy
    float depth = 0.0;
    float spiral = 0.0;
    float width = 0.3;  // Thu nhỏ độ rộng để tăng chi tiết
    float arms = 4.0;   // Tăng số cánh xoáy
    float time = iTime * 1.5;

    // Tạo nhiều lớp với độ sâu khác nhau
    for(float i = 0.0; i < 4.0; i++) {
        float z = 1.0 - i * 0.2;  // Giảm khoảng cách giữa các lớp

        // Điều chỉnh scale và tốc độ theo độ sâu
        float scale = mix(1.0, 2.0, z);  // Tăng scale variation
        float speed = mix(0.5, 1.5, z);  // Tăng speed variation

        // Tính toán SDF với hiệu ứng tunnel
        float r = dist * arms * scale * (1.0 + tunnelDepth);
        float theta = atan(uv.y, uv.x) * arms;
        float phase = time * speed;

        // Thêm biến dạng theo độ sâu
        float depthWarp = sin(dist * 5.0 - phase) * 0.3 * tunnelDepth;
        theta += depthWarp * z;

        // Tính SDF với độ sâu
        float d = abs(mod(theta + r - phase, 2.0 * 3.14159) - 3.14159) / (3.14159);
        float layerSpiral = smoothstep(width * z, 0.0, d);

        // Tăng cường lighting theo độ sâu
        float lighting = 1.0 - abs(d - width * 0.5) / width;
        lighting = pow(lighting, 3.0) * z * (1.0 + tunnelDepth);

        spiral += layerSpiral * z;
        depth += lighting * layerSpiral;
    }

    // Màu với độ sâu tăng cường
    vec3 color1 = vec3(0.5, 0.0, 1.0);
    vec3 color2 = vec3(0.0, 0.4, 1.0);
    vec3 color3 = vec3(1.0, 0.2, 0.5);

    // Mix màu với hiệu ứng độ sâu
    vec3 color = mix(
        mix(color1, color2, spiral),
        color3,
        smoothstep(0.4, 0.8, spiral * tunnelDepth)
    );

    // Tăng cường hiệu ứng depth
    float fade = smoothstep(1.8, 0.1, dist);
    float tunnelGlow = exp(-dist * 1.5) * 1.2;

    // Thêm hiệu ứng ánh sáng theo độ sâu
    color *= (1.0 + depth * 0.8 * tunnelDepth) * fade;
    color += vec3(0.4, 0.2, 1.0) * tunnelGlow;

    // Tăng cường độ tối ở xa
    color *= mix(1.0, 0.2, tunnelDepth);

    // Thêm stars/highlights ở xa
    float stars = pow(max(0.0, 1.0 - length(uv * 2.0)), 8.0) * tunnelDepth;
    color += vec3(1.0, 0.8, 1.0) * stars;

    fragColor = vec4(color, 1.0);
}
